    ws = wb[name]
    print(name, ws.max_row, ws.max_column)
    for r in range(1, min(30, ws.max_row+1)):
        row = [ws.cell(r, c).value for c in range(1, ws.max_column+1)]
        if any(row):
            print(f"R{r}: {row}")
