    for r in range(1, ws.max_row+1):
        row = [ws.cell(r, c).value for c in range(1, ws.max_column+1)]
        s = " ".join(str(x) for x in row if x is not None).lower()
        if any(w in s for w in ["school", "library", "water", "community", "city", "town", "district", "craven", "darn", "holc", "lock", "marden", "tres"]):
            print(f"Match R{r}: {row}")
