import os, glob, openpyxl, docx

terms = ["cravenwood", "darnwick", "holcott", "lockmere", "marden", "tresbay", "0779", "0793", "0061", "arvexa", "selvix", "solmery", "torvane", "vexlar", "witness", "eng-prc-014"]

for root, dirs, files in os.walk("/filesystem"):
    for f in files:
        if f.startswith("._"): continue
        p = os.path.join(root, f)
        ext = os.path.splitext(f)[1].lower()
        text = ""
        try:
            if ext in [".txt", ".md", ".eml", ".csv", ".json"]:
                text = open(p, errors="ignore").read()
            elif ext == ".xlsx":
                wb = openpyxl.load_workbook(p, data_only=True)
                for s in wb.sheetnames:
                    ws = wb[s]
                    for row in ws.iter_rows(values_only=True):
                        text += " ".join(str(x) for x in row if x is not None) + "\n"
            elif ext == ".docx":
                d = docx.Document(p)
                text = "\n".join(par.text for par in d.paragraphs)
                for t in d.tables:
                    for row in t.rows:
                        text += "\n" + " | ".join(c.text.strip() for c in row.cells)
        except Exception as e:
            pass
        if text:
            matches = [t for t in terms if t in text.lower()]
            if matches:
                print(f"{p}: {matches}")
